import{z as i,x as B,o as r,c as m,q as n,j as l,D as s,d as o,s as E,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"van Emde Boas","description":"","frontmatter":{"title":"van Emde Boas","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/van-emde-boas.md","filePath":"cs/van-emde-boas.md","lastUpdated":1791413859000}'),A={name:"cs/van-emde-boas.md"};function p(c,a,h,g,D,U){const t=B("Mermaid");return r(),m("div",null,[a[2]||(a[2]=n('<h1 id="van-emde-boas" tabindex="-1">van Emde Boas <a class="header-anchor" href="#van-emde-boas" aria-label="Permalink to &quot;van Emde Boas&quot;">​</a></h1><div class="epigraph"><p>把 $[0,U)$ 对半切成 $\\sqrt{U}$ 个簇，再递归；前驱后继跟着高位走簇、低位走内部，时间 $O(\\log\\log U)$。</p><footer>—— 据 van Emde Boas, Preserving Order in a Forest, FOCS 1975 / Math. Systems Theory 1977；Cormen, Leiserson, Rivest and Stein 第 20 章整理</footer></div><p><a href="/cs/double-ended-pq">上一课</a> 与比较堆在任意有序域上是 \\(\\Theta(\\log n)\\)。键若是机器字宇宙 \\([0,U)\\)，\\(n\\) 可以远小于 \\(U\\)，比较模型不是唯一选择。<a href="/cs/trie">Trie</a> 按比特下降是 \\(O(w)\\)。本课不维护堆序。缺口是 van Emde Boas 树：递归平方根切分，<code>insert</code>/<code>delete</code>/<code>successor</code> \\(O(\\log\\log U)\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>需要有序整数集：成员、前驱、后继。平衡 BST 不知 \\(U\\)。vEB：结构含 <code>min</code>、<code>max</code>、一个 <code>summary</code> vEB（哪些簇非空）、以及 \\(\\sqrt{U}\\) 个簇各一棵子 vEB。高位 \\(\\lfloor x/\\sqrt{U}\\rfloor\\) 选簇，低位 \\(x\\bmod\\sqrt{U}\\) 在簇内。后继：簇内有则递归；否则 summary 上找下一个非空簇再取其 min。缺口是<strong>宇宙大小进递归深度</strong> \\(\\log\\log U\\)，不是 \\(n\\)。</p><p><span class="marginnote">空结构只存 min/max 的原型可降空间。完整数组簇是 \\(\\Theta(U)\\) 空间，须用哈希簇才接近 \\(O(n)\\)，那是 y-fast 的动机之一。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>插入：空则只写 min；否则维护 min 不变式（更小的键顶替 min，旧 min 插进簇），再更新 summary。删除对称，注意 min 无簇副本的设计变体。递归底：\\(U=2\\) 存两比特。</p>',8)),(r(),l(d,null,{default:s(()=>[E(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E9%94%AE%20x%22%5D%20--%3E%20HI%5B%22%E7%B0%87%E5%8F%B7%20%3D%20%E9%AB%98%E4%BD%8D%22%5D%0A%20%20X%20--%3E%20LO%5B%22%E7%B0%87%E5%86%85%20%3D%20%E4%BD%8E%E4%BD%8D%22%5D%0A%20%20SUM%5B%22summary%3A%20%E5%93%AA%E4%BA%9B%E7%B0%87%E9%9D%9E%E7%A9%BA%22%5D%20--%3E%20NXT%5B%22%E8%B7%A8%E7%B0%87%E5%90%8E%E7%BB%A7%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与位图：位图后继是扫字，\\(\\Theta(U/w)\\) 最坏一段；vEB 保证 \\(\\log\\log U\\)。\\(U=2^{32}\\) 时 \\(\\log\\log U=5\\)，常数与实现相关。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"时间递推 \\(T(U)=T(\\sqrt{U})+O(1)\\) 得 \\(O(\\log\\log U)\\)。空间朴素 \\(\\Theta(U)\\)。不要在 \\(U\\) 超大时无哈希地分配簇数组。比较模型下信息下界仍 \\(\\log n\\)；vEB 用了键是整数这一限制。",-1)),a[6]||(a[6]=e("p",null,[o("一次 "),e("code",null,"successor(x)"),o(" 的完整行走路线——先看本簇右侧，不行才跳到 summary：")],-1)),(r(),l(d,null,{default:s(()=>[E(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22successor(x)%22%5D%20--%3E%20SPLIT%5B%22%E9%AB%98%E4%BD%8D%20h%20%E9%80%89%E7%B0%87%2C%20%E4%BD%8E%E4%BD%8D%20l%22%5D%0A%20%20SPLIT%20--%3E%20C1%7B%22l%20%5Clt%20%E6%9C%AC%E7%B0%87%20max%20%3F%22%7D%0A%20%20C1%20--%3E%7C%E6%98%AF%7C%20IN%5B%22%E7%B0%87%E5%86%85%E9%80%92%E5%BD%92%E6%B1%82%20l%20%E7%9A%84%E5%90%8E%E7%BB%A7%3Cbr%2F%3E%E6%8B%BC%E5%9B%9E%20h%C2%B7%E2%88%9AU%20%2B%20%E7%AD%94%E6%A1%88%22%5D%0A%20%20C1%20--%3E%7C%E5%90%A6%7C%20C2%7B%22x%20%5Clt%20%E5%85%A8%E5%B1%80%20max%20%3F%22%7D%0A%20%20C2%20--%3E%7C%E5%90%A6%7C%20NONE%5B%22%E6%97%A0%E5%90%8E%E7%BB%A7%2C%20%E8%BF%94%E5%9B%9E%E7%A9%BA%22%5D%0A%20%20C2%20--%3E%7C%E6%98%AF%7C%20SUM%5B%22summary%20%E4%B8%8A%E6%B1%82%20h%20%E7%9A%84%E5%90%8E%E7%BB%A7%20h'%22%5D%0A%20%20SUM%20--%3E%20MIN%5B%22%E7%AC%AC%20h'%20%E7%B0%87%E9%9D%9E%E7%A9%BA%2C%20%E5%8F%96%E5%85%B6%20min%22%5D%0A%20%20MIN%20--%3E%20ANS%5B%22%E7%AD%94%E6%A1%88%20%3D%20h'%C2%B7%E2%88%9AU%20%2B%20min%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">数字实例：取 \\(U=2^{32}\\)（32 位整数宇宙），\\(\\log\\log U=\\log 32=5\\)——无论集合里存 \\(10\\) 个还是 \\(10^6\\) 个键，一次后继最多下探约 5 层；同规模的平衡 BST 要走 \\(\\log_2 10^6\\approx 20\\) 层。这是用「键必须是小整数」换来的量级差。</span></p><p><span class="marginnote">直觉类比：把宇宙想成一栋 \\(\\sqrt U\\) 层、每层 \\(\\sqrt U\\) 个柜子的楼。<code>summary</code> 是大厅的楼层指示牌，只记「哪层还有东西」。找后继时先翻自己这层（簇内递归），翻不到就抬头看指示牌跳到下一个有货的层，直接取那层最靠前的柜子（簇的 min）——不用一层层扫楼。</span></p><p><span class="marginnote">常见误区：按定义直接实现，空间是 \\(\\Theta(U)\\)——\\(U=2^{32}\\) 时哪怕只存一个键，簇数组也按 40 多亿个槽铺开。工程做法是用哈希表只存非空簇，空间落到接近 \\(O(n)\\)；这正是后课 y-fast trie 改造 vEB 的动机。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 x-fast trie 的全部分层位图写完——下一课 y-fast 用 x-fast 加平衡树块把空间收到 \\(O(n)\\)。也不把融合树的 \\(O(\\log n/\\log\\log n)\\) 写进来。</p><p>后课默认：宇宙 \\(U\\) 已知时后继可以 \\(\\log\\log U\\)。线性空间用 y-fast trie。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>vEB：平方根分簇，前驱后继 \\(O(\\log\\log U)\\)。</li><li>朴素空间 \\(\\Theta(U)\\)；要 \\(O(n)\\) 空间看 y-fast。</li><li>出处：van Emde Boas, 1975/1977；Cormen et al. 第 20 章。</li></ul>',8))])}const f=i(A,[["render",p]]);export{C as __pageData,f as default};
